interface.definition:
a!localVariables(
  local!bUs: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3084520"(
    regionId: ri!rotationalAsk.regionId,
    isActive: true,
    columns: {
      "buId",
      "regionId",
      "bu"
    },
    returnCDT: true
  ),
  local!totalVersions: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3338676"(
    askId: ri!rotationalAsk.askId,
    columns: "askId",
    returnCDT: true
  ),
  local!totalVersionCount: length(local!totalVersions),
  local!isOldVersion:if(
    a!isNullOrEmpty(ri!rotationalAsk.createdOn),
    false,
    if(
      todatetime(ri!rotationalAsk.createdOn)<#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false)
  ),
  {
    #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3781239"(
      reportName: "ASK Home",
      report: #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3725690",
      recordName: if(
        todate(
          ri!rotationalAsk.createdOn
        ) < todate(#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045"),
        concat(
          "Rotational " & ri!rotationalAsk.region & " "
          & ri!rotationalAsk.fYear & " : " & ri!rotationalAsk.askId & " - V" & ri!rotationalAsk.version 
        ),
        concat(
        "Rotational " & ri!rotationalAsk.askName & " : " & ri!rotationalAsk.askId & " - V" & ri!rotationalAsk.version 
      ))
      /*recordName: concat(*/
        /*"Rotational " & ri!rotationalAsk.askId & " - V" & ri!rotationalAsk.version */
      /*)*/
    ),
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_boxLayout"(
              label: "Rotational Details",
              contents: {
                #"SYSTEM_SYSRULES_columnsLayout"(
                  spacing: "DENSE",
                  columns:if(toboolean(local!isOldVersion)=true,
                  {


                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Region",
                          labelPosition: "ABOVE",
                          align: "LEFT",
                          value: index(ri!rotationalAsk,"region",tostring(null)),
                          readOnly: true
                        )
                      }
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Version",
                          labelPosition: "ABOVE",
                          align: "LEFT",
                          value: index(ri!rotationalAsk,"version",tostring(null)),
                          readOnly: true
                        )
                      }
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Request #",
                          labelPosition: "ABOVE",
                          value: index(ri!rotationalAsk,"askId",tostring(null)),
                          readOnly: true
                        )
                      }
                    )
                  },
                  {


                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Region",
                          labelPosition: "ABOVE",
                          align: "LEFT",
                          value: index(ri!rotationalAsk,"region",tostring(null)),
                          readOnly: true
                        )
                      },
                      width: "EXTRA_NARROW",
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Name of the ASK",
                          labelPosition: "ABOVE",
                          align: "LEFT",
                          value: index(ri!rotationalAsk,"askName",tostring(null)),
                          readOnly: true
                        )},

                      width: "2X",
                      showWhen: if(toboolean(local!isOldVersion)=true,false,true)
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Fiscal Year of ASK",
                          labelPosition: "ABOVE",
                          align: "LEFT",
                          value: index(ri!rotationalAsk,"fYear",tostring(null)),
                          readOnly: true

                        )
                      },
                      width: "2X",
                      showWhen: if(toboolean(local!isOldVersion)=true,false,true)
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Version",
                          labelPosition: "ABOVE",
                          align: "LEFT",
                          value: index(ri!rotationalAsk,"version",tostring(null)),
                          readOnly: true
                        )
                      },
                      /*width: "NARROW"*/
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_textField"(
                          label: "Request #",
                          labelPosition: "ABOVE",
                          value: index(ri!rotationalAsk,"askId",tostring(null)),
                          readOnly: true
                        )
                      },
                      /*width: "NARROW"*/
                    )
                  }
                ))
              },
              style: "ACCENT",
              marginBelow: "STANDARD"
            ),
            #"SYSTEM_SYSRULES_boxLayout"(
              label: "BU Summary",
              contents: {
                #"SYSTEM_SYSRULES_gridLayout"(
                  headerCells: {
                    #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "BU", align: "CENTER" ),
                    #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Plan", align: "CENTER" )
                  },
                  rows: {
                    #"SYSTEM_SYSRULES_forEach"(
                      items: ri!rotationalAskDetails,
                      expression: #"SYSTEM_SYSRULES_gridRowLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_textField"(
                            label: "",
                            value: property(
                              index(
                                local!bUs,
                                wherecontains(
                                  tointeger(fv!item.buId),
                                  tointeger(property(local!bUs,"buId",null))
                                ),
                                {}
                              ),
                              "bu",
                              null
                            ),
                            readOnly: true,
                            align: "CENTER"
                          ),
                          #"SYSTEM_SYSRULES_integerField"(
                            value: if(
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(index(fv!item, "plan",tointeger({}))),
                              0,
                              index(fv!item, "plan",tointeger({}))
                            ),
                            readOnly: true,
                            align: "CENTER"
                          )
                        }
                      )
                    ),
                    #"SYSTEM_SYSRULES_gridRowLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: "Total",
                            size: "MEDIUM",
                            style: "STRONG"
                          ),
                          align: "CENTER"
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value:  #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: sum(
                              #"SYSTEM_SYSRULES_forEach"(
                                items: ri!rotationalAskDetails,
                                expression: index(fv!item,"plan",tointeger(null))
                              )
                            ),
                            style: "STRONG"
                          ),                           
                          align: "CENTER"
                        )
                      }
                    )
                  },
                  spacing: "DENSE"
                )
              },
              style: "ACCENT",
              marginBelow: "STANDARD"
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: {
                                "CURRENT STATUS"
                              },
                              color: "SECONDARY",
                              size: "MEDIUM",
                              style: {
                                "STRONG"
                              }
                            )
                          },
                          align: "CENTER"
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextIcon"(icon: "clock-o", size: "LARGE"),
                            "   ",
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: tostring(ri!rotationalAsk.status),
                              size: "MEDIUM_PLUS"
                            )


                          },
                          align: "CENTER"
                        )
                      }
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: {
                                "TOTAL PLAN"
                              },                      color: "SECONDARY",
                              size: "MEDIUM"
                              ,
                              style: {
                                "STRONG"
                              }
                            )
                          },
                          align: "CENTER"
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextIcon"(icon: "users", size: "LARGE"),
                            "   ",
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: sum(ri!rotationalAskDetails.plan),
                              size: "LARGE"
                            )

                          },
                          align: "CENTER"
                        )
                      }
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: {
                                "TOTAL VERSIONS"
                              },
                              color: "SECONDARY",
                              size: "MEDIUM",
                              style: {
                                "STRONG"
                              }
                            )
                          },
                          align: "CENTER"
                        ),
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextIcon"(icon: "copy", size: "LARGE"),
                            "   ",
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: tointeger(local!totalVersionCount),
                              size: "LARGE"
                            )

                          },
                          align: "CENTER"
                        )
                      }
                    )
                  }
                )
              },
              style: "INFO",
              marginBelow: "STANDARD"
            ),
            #"SYSTEM_SYSRULES_boxLayout"(
              label: "Last Modified By & On",
              contents: {
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_imageField_v1"(
                        labelPosition: "COLLAPSED",
                        images: #"SYSTEM_SYSRULES_userImage"(
                          user: ri!rotationalAsk.modifiedBy
                        ),
                        size: "SMALL",
                        style: "AVATAR"
                      ),
                      width: "MINIMIZE"
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(touser(index(ri!rotationalAsk, "modifiedBy", tostring(null)))),
                            link: #"SYSTEM_SYSRULES_userRecordLink"(
                              user: ri!rotationalAsk.modifiedBy
                            ),
                            linkStyle: "STANDALONE",
                            size: "MEDIUM",
                            style: "STRONG"
                          )
                        }
                      )
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: index(ri!rotationalAsk, "modifiedOn", tostring(null)),
                            color: "SECONDARY",
                            size: "MEDIUM"
                          )
                        }
                      ),
                      width: "MINIMIZE"
                    )
                  },
                  alignvertical: "MIDDLE"
                )
              },
              style: "ACCENT",
              shape: "SQUARED",
              marginBelow: "STANDARD"
            ),
            #"SYSTEM_SYSRULES_boxLayout"(
              label: "Created By & On",
              contents: {
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_imageField_v1"(
                        labelPosition: "COLLAPSED",
                        images: #"SYSTEM_SYSRULES_userImage"(
                          ri!rotationalAsk.createdBy
                        ),
                        size: "SMALL",
                        style: "AVATAR"
                      ),
                      width: "MINIMIZE"
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text:  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(touser(index(ri!rotationalAsk, "createdBy", tostring(null)))),
                            link: #"SYSTEM_SYSRULES_userRecordLink"(
                              user: ri!rotationalAsk.createdBy
                            ),
                            linkStyle: "STANDALONE",
                            size: "MEDIUM",
                            style: "STRONG"
                          )
                        }
                      )
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: index(ri!rotationalAsk, "createdOn", tostring(null)),
                            color: "SECONDARY",
                            size: "MEDIUM"
                          )
                        }
                      ),
                      width: "MINIMIZE"
                    )
                  },
                  alignvertical: "MIDDLE"
                )
              },
              style: "ACCENT",
              marginBelow: "STANDARD"
            )
          }
        )
      }
    )
  }
)
